uses uSpaceAge;

{ SpaceAgeTests }

procedure SpaceAgeTests.Age_on_earth;
var
  MyAge: ISpaceAge;
  expectedAge: double;
begin
  MyAge := NewSpaceAge(1000000000);
  expectedAge := 31.69;
  Assert.AreEqual(expectedAge, MyAge.OnEarth);
end;

